-- ============================================================================
--  泡泡战士 CN0261 · 回退脚本
--  对应补丁：weapons-patch.sql（武器 31 件）
--  说明：棒棒大锤 红(207039) / 绿(207040) 已从补丁剔除，这里不涉及；
--        要单独清理它们用 maintenance/2026-11-15-recall-hammer-red-green.sql
--
--  行为：先查有没有玩家买过 → 有就一并回收（删背包持有 / 武器预设 / 购买记录）
--        → 再删商店数据（库存 / 上架 / 规则 / 定义）。跑完商店和背包都干净。
--
--  用法：mariadb <库名> < 本文件
--  幂等：可重复执行
--  ⚠ 回收没有备份（按约定不做备份表），玩家已买的道具会被直接没收。
-- ============================================================================
SET NAMES utf8mb4;

-- ---------------------------------------------------------------------------
-- 1) 先看清楚：谁持有这些道具（只读，不动数据）
-- ---------------------------------------------------------------------------
SELECT ci.character_id, c.nickname AS character_name, ci.item_id, d.name,
       ci.quantity, ci.equipped_slot
FROM character_items ci
JOIN characters c ON c.id = ci.character_id
LEFT JOIN item_definitions d ON d.id = ci.item_id
WHERE ci.item_id IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926);

SELECT i.item_id, d.name,
       (SELECT COUNT(*) FROM shop_stocks s WHERE s.item_id = i.item_id) AS stocks,
       (SELECT COUNT(*) FROM shop_purchases p JOIN shop_stocks s2 ON s2.id = p.stock_id
         WHERE s2.item_id = i.item_id) AS purchases
FROM shop_items i
LEFT JOIN item_definitions d ON d.id = i.item_id
WHERE i.item_id IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926);

START TRANSACTION;

-- ---------------------------------------------------------------------------
-- 2) 回收玩家侧数据（character_item_expirations 是 ON DELETE CASCADE，自动跟着删）
-- ---------------------------------------------------------------------------
DELETE FROM character_items                WHERE item_id IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926);
DELETE FROM character_weapon_preset_items  WHERE item_id IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926);
DELETE FROM character_appearances          WHERE item_id IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926);

-- ---------------------------------------------------------------------------
-- 3) 删商店数据（先叶子后根，避免外键报 1451）
-- ---------------------------------------------------------------------------
DELETE FROM shop_purchases
 WHERE stock_id IN (SELECT id FROM shop_stocks WHERE item_id IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926));
DELETE FROM shop_permanent_stocks
 WHERE stock_id IN (SELECT id FROM shop_stocks WHERE item_id IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926));
DELETE FROM shop_preview_items    WHERE item_id IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926);
DELETE FROM shop_stocks           WHERE item_id IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926);
DELETE FROM shop_items            WHERE item_id IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926);
DELETE FROM item_equipment_rules  WHERE item_id IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926);
DELETE FROM item_definitions      WHERE id      IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926);

COMMIT;

-- ---------------------------------------------------------------------------
-- 4) 自检：五个计数都应该 0
-- ---------------------------------------------------------------------------
SELECT
  (SELECT COUNT(*) FROM item_definitions     WHERE id      IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926)) AS defs_left,
  (SELECT COUNT(*) FROM shop_items           WHERE item_id IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926)) AS shop_left,
  (SELECT COUNT(*) FROM shop_stocks          WHERE item_id IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926)) AS stocks_left,
  (SELECT COUNT(*) FROM character_items      WHERE item_id IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926)) AS in_bags_left,
  (SELECT COUNT(*) FROM shop_purchases p JOIN shop_stocks s ON s.id = p.stock_id
    WHERE s.item_id IN (201108, 201110, 201342, 202015, 202207, 202308, 202312, 202315, 202327, 202333, 202342, 202376, 202378, 203014, 203103, 203206, 203209, 203220, 203333, 203342, 203372, 203373, 204107, 204342, 204365, 204367, 204368, 207037, 207055, 207922, 207926))                                         AS purchases_left;
